/* q33_lam_a.js: Exam 3 (Dr. Lam, Lecture 12, glaucoma therapeutics), part A: collect (drugs that raise eye pressure, presentation, risk factors),
   assess (goal of therapy and target, the four medication-related problem categories) and the prostaglandin analogs (slides 6-25).
   Sources: Lam_Glaucoma.pdf (slide N = PDF page; slides 9-11 are the poll images), her handout Lam_Glaucoma_doc.docx (same text) and
   DEENT_Lecture_11.19_transcript.txt (T@n = character offset into that file, cited "11/19"). Ids LMA-*. Her two Ms. Lopez multiple-choice cases of
   this range (the drugs that worsen IOP, the BID bimatoprost prescription) are kept in her words as LMA-001 and LMA-002.
   Notes on sources: slide 19 prints Latisse 0.3% and the handout 0.03%, so no item uses that number; the handout lists Rocklatan once daily while
   she said combination products are never once daily (her table lists only BID and TID products), so Rocklatan is asked only by what it contains;
   frequency inappropriate is listed under both effectiveness and safety (slides 15-16), so no item asks which of the two a too-frequent
   prostaglandin prescription is. Marked lowYield (she said she would not test them): risk factors, reading a sig on its own (she said it will not be on the test),
   contraindications of prostaglandin analogs.
   Ids LMA-013, 015, 034, 038, 040, 041, 042, 044, 045, 049, 056 and 064 were removed after review (each asked a fact another item here asks, or had
   distractors no source supports); ids are not renumbered. */
QUESTIONS.push(
{id:"LMA-001", skill:"case", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-lopez-poll", multi:true,
 tags:["poll", "multi", "case"], source:"both",
 stem:"Ms. Lopez, a 68-year-old woman, presents to the pharmacy after being newly diagnosed with primary open-angle glaucoma. She is concerned about medications that may worsen their intraocular pressure. Her current medications include hydrochlorothiazide, sertraline, diphenhydramine, fluticasone nasal spray, atorvastatin, prednisolone eye drops. Which medications are likely to worsen intraocular pressure and should be discussed with the ordering provider of those medications? Select all that apply.",
 options:[
  {t:"Hydrochlorothiazide", correct:false, why:"A thiazide diuretic is neither a corticosteroid nor an anticholinergic, the two groups on her list of drugs that raise IOP, so it is not one to raise with a prescriber."},
  {t:"Sertraline", correct:false, why:"She said SSRIs have less anticholinergic activity than tricyclic agents, so sertraline is the less likely contributor and is not the drug to flag."},
  {t:"Diphenhydramine", correct:true, why:"An oral antihistamine (Benadryl) with anticholinergic activity; anticholinergics produce mydriasis and can induce or worsen glaucoma, so it is discussed with the prescriber."},
  {t:"Fluticasone nasal spray", correct:true, why:"A corticosteroid. Minimum systemic absorption makes it less likely to reach the eye, but she said a rise can happen and tends to occur in chronic users."},
  {t:"Atorvastatin", correct:false, why:"A statin is neither a corticosteroid nor an anticholinergic; her handout names those two groups as the drugs that induce glaucoma."},
  {t:"Prednisolone eye drops", correct:true, why:"A corticosteroid placed on the eye, the form she ranked highest in risk because it targets that organ."},
 ],
 teach:"Corticosteroids and anticholinergics are the two drug groups her handout names as inducing or worsening glaucoma, so each drug on a patient's list is sorted into one group or neither. Ophthalmic steroids rank highest, then systemic, then nasal or inhaled, and diphenhydramine is the anticholinergic antihistamine. The pharmacist discusses these drugs with their prescribers.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@45850, T@44371 11/19"},

{id:"LMA-002", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"case", concept:"lm-pga-lopez-frequency",
 tags:["poll", "case"], source:"both",
 stem:"Ms. Lopez, a 68-year-old woman, presents to the pharmacy after being newly diagnosed with primary open-angle glaucoma. She brings a new prescription for bimatoprost 0.01% ophthalmic solution, instill 1 drop OU BID. What is the medication-related problem? Select the most appropriate pharmacist response.",
 options:[
  {t:"The prescription is appropriate; dispense the prescription.", correct:false, why:"BID is the schedule of the beta blocker solutions in her handout; a prostaglandin analog is once daily, so dispensing as written repeats the frequency error."},
  {t:"The prescription is incorrect because the frequency is too frequent; contact provider", correct:true, why:"She said that dosing above once daily decreases a prostaglandin analog's efficacy, so the frequency is wrong and the pharmacist contacts the provider for a once-daily prescription."},
  {t:"The prescription is incorrect because the patient should use 2 drops instead of one.", correct:false, why:"Two drops raise the amount per use and do nothing for the schedule; the error she named is how many times a day the drop is used."},
  {t:"The prescription is incorrect because the frequency is too low.", correct:false, why:"Twice daily is more often than once daily, so the frequency is too high rather than too low."},
 ],
 teach:"A prostaglandin analog works best once a day, and dosing more often decreases its efficacy instead of adding to it. A bimatoprost prescription written BID is therefore a frequency error, and she said the pharmacist contacts the provider to clarify and obtain a new once-daily prescription. BID is the beta blocker schedule, so it is easy to mistake for appropriate.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 24–25; T@57313, T@57715, T@57882 11/19"},

{id:"LMA-003", skill:"class", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-formulation-highest",
 tags:["hard"], source:"both",
 stem:"A pharmacist reviews the medication list of a patient with primary open-angle glaucoma who needs a corticosteroid for a different condition. Which formulation carries the highest potential to raise intraocular pressure?",
 options:[
  {t:"Systemic corticosteroid", correct:false, why:"Systemic steroids come next after the ophthalmic route because less of the dose penetrates the eye."},
  {t:"Corticosteroid nasal spray", correct:false, why:"Minimum systemic absorption makes a nasal spray less likely to reach the eye; a rise can still occur in chronic users, but the risk is below the ophthalmic route."},
  {t:"Corticosteroid eye drops", correct:true, why:"She said the steroid that targets the organ has the highest potential to induce glaucoma, and an eye drop is placed on the eye itself."},
  {t:"Inhaled corticosteroid", correct:false, why:"Inhaled steroids are grouped with nasal ones at the bottom of her ranking, below systemic use."},
 ],
 teach:"How much corticosteroid reaches the eye sets the risk of raising IOP: the form that targets the eye is highest, and risk declines as less penetrates. For a glaucoma patient who needs a steroid elsewhere, the pharmacist weighs the route and whether use is temporary or chronic.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44371, T@44473 11/19"},

{id:"LMA-004", skill:"class", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-formulation-second",
 tags:["hard"], source:"both",
 stem:"Mr. Boateng, 70, has primary open-angle glaucoma and has taken prednisone tablets daily for months. Compared with corticosteroid eye drops and a corticosteroid nasal spray, where does his systemic steroid fall in risk of raising intraocular pressure?",
 options:[
  {t:"Below eye drops and above the nasal spray", correct:true, why:"Systemic steroids rank after the ophthalmic form because less drug penetrates the eye, and above nasal spray, which has minimum systemic absorption."},
  {t:"Above eye drops and above the nasal spray", correct:false, why:"Eye drops rank above systemic steroids because the drop targets the eye itself."},
  {t:"Below eye drops and below the nasal spray", correct:false, why:"A nasal spray has minimum systemic absorption, so it ranks under the systemic route, not over it."},
  {t:"Equal to the nasal spray and below eye drops", correct:false, why:"Systemic use ranks above the nasal spray because the nasal form has minimum systemic absorption, so the two are not equal."},
 ],
 teach:"Risk of raising IOP declines as less of the steroid penetrates the eye: ophthalmic is highest, systemic is next, and nasal or inhaled forms have minimum systemic absorption. Months of daily prednisone in a glaucoma patient is the chronic use in which she said a rise tends to occur, so the pharmacist raises it with the prescriber.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44371, T@44473, T@44677 11/19"},

{id:"LMA-005", skill:"case", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-nasal-chronic",
 tags:["hard", "case"], source:"both",
 stem:"A 66-year-old man with primary open-angle glaucoma has used fluticasone nasal spray daily for years for rhinitis. His provider has not discussed this with the eye doctor. What is the best pharmacist assessment?",
 options:[
  {t:"No relationship to IOP because the drug is given into the nose", correct:false, why:"Nasal steroids are less likely to get into the eye, not unable to; she said a rise can happen in chronic users."},
  {t:"Higher risk than eye drops because the dose is larger overall", correct:false, why:"Dose size does not set the ranking; the eye drop that targets the organ is highest and nasal sprays with minimum systemic absorption rank lower."},
  {t:"Risk begins after the first few doses, so stop it now", correct:false, why:"She tied the risk to chronic use, and the handout response is a discussion with the prescriber, not a stop after the first doses."},
  {t:"Less risk than eye drops, but chronic use can raise IOP", correct:true, why:"Minimum systemic absorption makes reaching the eye less likely than with eye drops, and years of daily use is the chronic pattern in which a rise tends to occur."},
 ],
 teach:"A nasal steroid has minimum systemic absorption, so it is less likely to reach the eye than an eye drop, but she said it can happen and tends to occur with chronic use. A glaucoma patient on a daily nasal steroid for years is that chronic user, so the pharmacist discusses it with the prescriber.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44677, T@44473 11/19"},

{id:"LMA-006", skill:"class", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-diphenhydramine-class",
 tags:["hard"], source:"both",
 stem:"A patient with open-angle glaucoma asks for an over-the-counter sleep aid containing diphenhydramine. Which property of this drug is the concern for glaucoma?",
 options:[
  {t:"Inhibition of carbonic anhydrase", correct:false, why:"Carbonic anhydrase inhibitors such as dorzolamide are glaucoma drugs that decrease aqueous humor production, so this property would treat glaucoma instead of worsening it."},
  {t:"Anticholinergic activity", correct:true, why:"Diphenhydramine (Benadryl) is her example of an anticholinergic antihistamine; anticholinergics produce mydriasis and can induce or worsen glaucoma."},
  {t:"Stimulation of alpha-2 receptors", correct:false, why:"Alpha-2 agonists such as brimonidine lower IOP and are glaucoma drugs, so this is not the concern."},
  {t:"Blockade of beta receptors", correct:false, why:"Beta blockers such as timolol lower IOP and are glaucoma drugs, so this is not the concern."},
 ],
 teach:"Anticholinergic drugs can induce or worsen glaucoma, and her handout gives mydriasis as their mechanism; Benadryl is her example. A glaucoma patient asking for an over-the-counter sleep aid containing diphenhydramine is the cue, and the pharmacist raises the anticholinergic effect. The other properties listed describe how glaucoma drugs lower IOP.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44943, T@45850 11/19"},

{id:"LMA-007", skill:"case", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-which-list-drug",
 tags:["hard", "case", "two-facts"], source:"both",
 stem:"Mrs. Cho, 71, has newly diagnosed primary open-angle glaucoma. Her list includes atorvastatin, hydrochlorothiazide, sertraline and a tricyclic antidepressant. Which drug is the most likely to contribute to her glaucoma?",
 options:[
  {t:"Sertraline, the SSRI antidepressant", correct:false, why:"She said SSRIs have less incidence of anticholinergic properties, so sertraline is less likely than the tricyclic to be the contributor."},
  {t:"Atorvastatin, the lipid-lowering drug", correct:false, why:"A statin is neither a corticosteroid nor an anticholinergic, the two groups she named as inducing glaucoma."},
  {t:"Hydrochlorothiazide, the diuretic", correct:false, why:"A thiazide diuretic is neither a corticosteroid nor an anticholinergic, so it fits neither group."},
  {t:"The tricyclic antidepressant", correct:true, why:"She named tricyclic antidepressants as the antidepressants with anticholinergic properties, and anticholinergics can induce or worsen glaucoma."},
 ],
 teach:"Antidepressants differ in anticholinergic activity: SSRIs have less and tricyclic agents more, and anticholinergics can induce or worsen glaucoma. The cue is an antidepressant on a glaucoma patient's list, and the pharmacist checks each drug's side effects against glaucoma. The SSRI is the nearest wrong option, because the tricyclic is the antidepressant she tied to anticholinergic effect.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44943 11/19"},

{id:"LMA-008", skill:"class", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-atropine-select", multi:true,
 tags:["hard", "multi"], source:"both",
 stem:"Which of these can raise intraocular pressure in a patient with primary open-angle glaucoma? Select all that apply.",
 options:[
  {t:"Prednisone tablets taken for months", correct:true, why:"A systemic corticosteroid; she ranked systemic use next after ophthalmic, and months of use is the chronic pattern."},
  {t:"Hydrochlorothiazide taken in the morning", correct:false, why:"A thiazide diuretic is neither a corticosteroid nor an anticholinergic, so it is not on her list of drugs that raise IOP."},
  {t:"Atropine eye drops", correct:true, why:"Atropine eye drops are her example of a topical anticholinergic; anticholinergics produce mydriasis and can raise IOP."},
  {t:"Atorvastatin", correct:false, why:"A statin belongs to neither group; she named corticosteroids and anticholinergics as the drugs that induce glaucoma."},
  {t:"Oral diphenhydramine at bedtime", correct:true, why:"An oral antihistamine is her example of a systemic anticholinergic, which can induce or worsen glaucoma."},
 ],
 teach:"Two groups raise IOP: corticosteroids, mainly with chronic use, and anticholinergics, which produce mydriasis. Each group appears as an eye drop and as a systemic drug: prednisone for steroids, atropine drops or an oral antihistamine for anticholinergics. A statin and a thiazide diuretic fit neither group, so the pharmacist does not flag them.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 8 and the handout section on drug-induced glaucoma; T@44050, T@44943 11/19"},

{id:"LMA-009", skill:"class", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-formulation-statements", multi:true,
 tags:["hard", "multi"], source:"both",
 stem:"How does the formulation of a corticosteroid affect its risk of raising intraocular pressure? Select all that apply.",
 options:[
  {t:"A nasal spray carries a higher risk than an eye drop", correct:false, why:"A nasal spray has minimum systemic absorption and ranks below eye drops, so this statement reverses the order."},
  {t:"The eye drop formulation carries the highest risk", correct:true, why:"The steroid that targets the eye has the highest potential to induce glaucoma, and the risk declines as less of it penetrates the eye."},
  {t:"A single dose is as likely to raise IOP as months of use", correct:false, why:"She tied the rise to chronic use, so a single dose is not equivalent to months of use."},
  {t:"Systemic steroids are the next highest risk", correct:true, why:"Systemic steroids rank after ophthalmic ones because less drug penetrates the eye, and above nasal or inhaled forms."},
  {t:"Nasal sprays carry less risk, but a rise can occur", correct:true, why:"Minimum systemic absorption makes the eye less likely to be reached, but she said it can happen, mostly in chronic users."},
 ],
 teach:"The amount of corticosteroid that penetrates the eye sets the risk: ophthalmic is highest, systemic is next, and nasal or inhaled is lowest because of minimum systemic absorption. Duration matters too, since a rise tends to occur in patients using these drugs chronically. For a glaucoma patient, the pharmacist weighs the route and whether use is temporary or chronic.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11; T@44371, T@44473, T@44677 11/19"},

{id:"LMA-010", skill:"mech", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-anticholinergic-effect",
 tags:["hard", "mechanism"], source:"both",
 stem:"Atropine eye drops and oral antihistamines can raise intraocular pressure in some patients through which effect?",
 options:[
  {t:"Miosis", correct:false, why:"Miosis is pupil constriction, the effect of a cholinergic such as pilocarpine, which lowers IOP by increasing outflow instead of raising it."},
  {t:"Decreased aqueous humor production", correct:false, why:"Decreased aqueous humor production is how beta blockers, topical carbonic anhydrase inhibitors and alpha-2 agonists lower IOP, so it describes treatment rather than drug-induced glaucoma."},
  {t:"Mydriasis", correct:true, why:"Her handout lists mydriasis, a dilated pupil, as the mechanism of anticholinergics, which is how atropine drops or an antihistamine can induce or worsen glaucoma."},
  {t:"Increased aqueous humor outflow", correct:false, why:"Increased aqueous humor outflow is how prostaglandin analogs and cholinergics lower IOP, which is the opposite direction from a rise."},
 ],
 teach:"Her handout gives mydriasis, a dilated pupil, as the mechanism by which anticholinergics induce glaucoma. The cue is a glaucoma patient using atropine drops or taking an antihistamine, and the pharmacist discusses it with the prescriber. Pilocarpine, a cholinergic, does the opposite to the pupil, causing constriction, and lowers IOP.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 8 and the handout section on drug-induced glaucoma; T@44943 11/19"},

{id:"LMA-011", skill:"case", prof:'Lam', tier:'new', topic:"lm-collect", sub:"drugs", concept:"lm-collect-reverse-ioprise",
 tags:["hard", "case"], source:"both",
 stem:"A 74-year-old woman with open-angle glaucoma used latanoprost 1 gtt OU QHS for a year with her IOP at target. Her IOP is now above target. She instills the latanoprost every evening with correct technique. Four months ago she began prednisolone eye drops after a corneal procedure. What is the best pharmacist response before any change in her glaucoma regimen?",
 options:[
  {t:"Reassure her, since eye drops are the lowest-risk steroid form", correct:false, why:"Ophthalmic corticosteroids carry the highest risk of raising IOP, so the drops are a likely cause and not a safe form."},
  {t:"Discuss the prednisolone drops with the prescriber", correct:true, why:"IOP rose after a corticosteroid started while latanoprost was used correctly, which points to the steroid; drugs that worsen IOP are discussed with the prescriber."},
  {t:"Raise latanoprost to twice daily for a stronger effect", correct:false, why:"Latanoprost is once daily, and dosing above that decreases efficacy, so twice daily would not help."},
  {t:"Switch latanoprost to bimatoprost, which is slightly more effective", correct:false, why:"Bimatoprost is slightly more effective, but a switch is the step for an inadequate response after compliance and technique are checked; here a corticosteroid was added first."},
 ],
 teach:"A new rise in IOP in a patient who was at target and still adheres with good technique points to something that changed, and a recently started corticosteroid or anticholinergic is the likely cause. Ophthalmic corticosteroids carry the highest risk, so the pharmacist discusses the drops with the prescriber before changing the glaucoma drug.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 8–11, 15; T@44371, T@45850 11/19"},

{id:"LMA-012", skill:"case", prof:'Lam', tier:'new', topic:"lm-collect", sub:"pres", concept:"lm-collect-asymptomatic-counsel",
 tags:["hard", "case", "counsel"], source:"both",
 stem:"Mr. Rivera, 63, says his vision is fine and asks why he needs eye drops every day for newly diagnosed primary open-angle glaucoma. What is the best explanation?",
 options:[
  {t:"It is silent until substantial visual field loss occurs", correct:true, why:"Open-angle glaucoma tends to be asymptomatic until substantial visual field loss, so normal-feeling vision does not show that treatment is unneeded; the drops lower IOP."},
  {t:"Mild eye pain would warn him as soon as the pressure rose", correct:false, why:"Intense eye pain is listed for the acute closed-angle presentation, not for open-angle glaucoma, which is asymptomatic."},
  {t:"Halos around lights would signal that the drops are needed", correct:false, why:"Halos around lights are listed under primary closed-angle glaucoma, not open-angle."},
  {t:"Headache and nausea tell him when the pressure is high", correct:false, why:"Headache with nausea and vomiting is an acute closed-angle symptom in her handout, not the open-angle presentation."},
 ],
 teach:"Primary open-angle glaucoma is asymptomatic until substantial visual field loss occurs, so symptoms cannot signal when the pressure is high. A patient who says his vision is fine still needs the daily drops, because the goal of therapy is reducing IOP. Pain, halos, headache and nausea belong to the closed-angle presentation in her handout.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 12; T@46365 11/19"},

{id:"LMA-014", skill:"epi", prof:'Lam', lowYield:true, tier:'new', topic:"lm-collect", sub:"risk", concept:"lm-collect-risk-factor",
 tags:["hard", "list"], source:"both",
 stem:"Which of the following is a risk factor for primary open-angle glaucoma?",
 options:[
  {t:"Thicker central corneal thickness", correct:false, why:"The handout lists a thinner, not a thicker, central corneal thickness as a risk factor."},
  {t:"Higher ocular perfusion pressure", correct:false, why:"The handout lists a lower, not a higher, ocular perfusion pressure as a risk factor."},
  {t:"Myopia", correct:true, why:"Myopia is on the handout's list of risk factors, alongside older age, family history, high IOP above 22 mm Hg and type 2 diabetes."},
  {t:"Younger age", correct:false, why:"Risk increases with age, so older age, not younger age, is the risk factor."},
 ],
 teach:"Risk of primary open-angle glaucoma rises with older age, family history, non-Hispanic white race in the US, high IOP above 22 mm Hg, type 2 diabetes, myopia, thinner central corneal thickness and lower ocular perfusion pressure. In a patient case, these items in the history are the cues for risk. Thickness and perfusion pressure are listed as thinner and lower.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 7"},

{id:"LMA-016", skill:"class", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-goal",
 tags:["hard"], source:"both",
 stem:"What is the goal of drug therapy in primary open-angle glaucoma?",
 options:[
  {t:"Reduce intraocular pressure", correct:true, why:"She said the one thing to know is that the goal is to reduce IOP, with the target determined by an eye care professional."},
  {t:"Dilate the pupil to widen the drainage angle", correct:false, why:"Pupil dilation is mydriasis, the mechanism of anticholinergics that can induce or worsen glaucoma, so it works against the goal."},
  {t:"Relieve eye pain and redness", correct:false, why:"Open-angle glaucoma is asymptomatic early, so pain is not what therapy treats; redness relief is the use of OTC brimonidine (Lumify), not glaucoma therapy."},
  {t:"Restore central vision lost to the disease", correct:false, why:"Therapy aims to lower IOP; her handout does not list restoring lost vision as a goal."},
 ],
 teach:"The goal of glaucoma therapy is to reduce IOP, and an eye care professional sets the target. Because the disease is asymptomatic until substantial visual field loss, the pharmacist judges treatment by IOP and not by how the patient feels. Each drug is then weighed on efficacy and safety against that goal.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 13–14; T@47294 11/19"},

{id:"LMA-017", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-who-target",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Dube, 69, asks the pharmacist what her pressure target is. Who determines the IOP target for a patient with glaucoma?",
 options:[
  {t:"The dispensing pharmacist from the drug chosen", correct:false, why:"She said the target is often determined by the ophthalmologist or optometrist, not by the dispensing pharmacist."},
  {t:"An ophthalmologist or optometrist", correct:true, why:"She said an ophthalmologist or optometrist often determines the target IOP, and the pharmacist works with that target."},
  {t:"The patient from her symptoms", correct:false, why:"The disease is asymptomatic until substantial visual field loss, so symptoms cannot give a pressure target."},
  {t:"The manufacturer from the product label", correct:false, why:"A product label carries no patient measurements; the target is set for the patient by an eye care professional."},
 ],
 teach:"The IOP target is set by an eye care professional, an ophthalmologist or optometrist. The pharmacist takes that target and the baseline IOP and then judges whether each drug is appropriate, effective, safe and taken as directed. Symptoms and drug labels do not set the target.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 14; T@47391, T@47427 11/19"},

{id:"LMA-018", skill:"dose", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-initial-target",
 tags:["hard", "recall"], source:"both",
 stem:"When the baseline intraocular pressure is above 22 mm Hg, what is the initial target reduction?",
 options:[
  {t:"10-15% lower", correct:false, why:"A 10-15% fall is below the 25-30% initial target."},
  {t:"At least 33% lower", correct:false, why:"33% is the reduction up to which prostaglandin analogs lower IOP, not the initial target, which is 25-30%."},
  {t:"25-30% lower", correct:true, why:"Her initial target for a baseline above 22 mm Hg is a 25-30% decrease in IOP."},
  {t:"45-50% lower", correct:false, why:"A 45-50% fall is far beyond the 25-30% initial target and is not a figure in her handout."},
 ],
 teach:"When the baseline IOP is above 22 mm Hg, the initial goal is a proportional fall of 25-30% from that patient's own baseline, not a fixed pressure. This is why she compares each drug's percent reduction with the goal: prostaglandin analogs lower IOP by up to 33%, which meets it.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 14; T@47427 11/19"},

{id:"LMA-019", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-compute-target",
 tags:["hard", "case", "calculation"], source:"both",
 stem:"Mr. Ng, 70, has a baseline IOP of 30 mm Hg. Using the initial target reduction of 25-30%, which post-treatment IOP meets it?",
 options:[
  {t:"25 mm Hg", correct:false, why:"A fall from 30 to 25 is 5 mm Hg, about 17%, short of 25-30%."},
  {t:"27.5 mm Hg", correct:false, why:"A fall from 30 to 27.5 is 2.5 mm Hg, about 8%, far short of 25-30%."},
  {t:"15 mm Hg", correct:false, why:"A fall from 30 to 15 is half, 50%, beyond the 25-30% initial target."},
  {t:"22 mm Hg", correct:true, why:"A fall from 30 to 22 is 8 mm Hg, about 27%, inside 25-30%; the range works out to 21 to 22.5 mm Hg."},
 ],
 teach:"The initial target is a percent of the patient's own baseline, so find 25% and 30% of the baseline and subtract each. For a baseline of 30 mm Hg, 25% is 7.5 and 30% is 9, so the target lies between 21 and 22.5 mm Hg. A value outside that range misses the goal.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 14; T@47427 11/19"},

{id:"LMA-020", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-goal-not-met",
 tags:["hard", "case", "calculation"], source:"both",
 stem:"Ms. Fraser, 66, had a baseline IOP of 26 mm Hg (above 22). After 6 weeks of therapy her eye doctor reports 21 mm Hg. Is she meeting the initial treatment goal?",
 options:[
  {t:"No, the fall is about 19%, below 25-30%", correct:true, why:"(26 minus 21) divided by 26 is about 19%, below 25-30%, so the goal is not met."},
  {t:"Yes, 21 mm Hg is below 22 mm Hg", correct:false, why:"Being just under 22 mm Hg is not the measure; the initial goal for a baseline above 22 is a percent fall."},
  {t:"Yes, a fall of a few mm Hg meets the goal", correct:false, why:"A fall of a few mm Hg needs a percent: 5 mm Hg from 26 is about 19%, short of 25-30%."},
  {t:"No, because the baseline was above 25 mm Hg", correct:false, why:"The baseline above 22 mm Hg sets the 25-30% target; the fall achieved, about 19%, decides whether it is met."},
 ],
 teach:"To judge whether the initial goal is met, convert the change to a percent of the baseline: baseline minus current, divided by baseline. Here 5 of 26 is about 19%, below the 25-30% goal, so she is not at goal, and the pharmacist then asks about adherence and technique.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 14; T@47427 11/19"},

{id:"LMA-021", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"goal", concept:"lm-assess-goal-met",
 tags:["hard", "case", "calculation"], source:"both",
 stem:"Mr. Daniels, 72, had a baseline IOP of 24 mm Hg. His eye doctor now measures 17 mm Hg on his regimen. Is he meeting the initial treatment goal?",
 options:[
  {t:"No, the fall is about 17%, below 25-30%", correct:false, why:"The fall is 7 of 24, about 29%, not 17%."},
  {t:"Yes, about 29% lower, within 25-30%", correct:true, why:"(24 minus 17) divided by 24 is about 29%, within 25-30%, so the goal is met."},
  {t:"No, the fall is about 40%, beyond 25-30%", correct:false, why:"A 40% fall would need an IOP near 14.4 mm Hg; 7 of 24 is about 29%."},
  {t:"No, because 17 mm Hg is below 22 mm Hg", correct:false, why:"17 mm Hg being below 22 does not decide it; the goal for a baseline above 22 is the percent fall."},
 ],
 teach:"Convert the change to a percent of the baseline before judging: baseline minus current, divided by baseline. A fall from 24 to 17 mm Hg is 7 of 24, about 29%, which lies inside the 25-30% target for a baseline above 22 mm Hg. A low-looking absolute value is not the test.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 14; T@47427 11/19"},

{id:"LMA-022", skill:"class", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-four-categories",
 tags:["hard", "recall"], source:"both",
 stem:"Which set lists the four categories used to assess each medication for a medication-related problem?",
 options:[
  {t:"Drug, dose, route, frequency, duration", correct:false, why:"Drug, dose, route, frequency and duration are the parts of a prescription written in the plan, not the assessment categories."},
  {t:"Indication, effectiveness, safety, and cost", correct:false, why:"Cost sits within her adherence category (cost-effective medication, cannot afford), so it is not a fourth category."},
  {t:"Indication, effectiveness, safety, adherence", correct:true, why:"Her handout assesses each medication for indication, effectiveness, safety and adherence."},
  {t:"Collect, assess, plan, implement and follow up", correct:false, why:"Collect, assess, plan, implement and follow up are the steps of the patient care process; the four categories sort problems within the assess step."},
 ],
 teach:"Within the assess step, every medication is checked in four categories: indication (is it needed), effectiveness (does it work at this dose and frequency), safety (adverse effect or unsafe drug for the patient) and adherence (does the patient take it, including cost). A case problem is placed in a category by asking which of these four it fails.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 13–16; T@48119 11/19"},

{id:"LMA-023", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-forgets-evening",
 tags:["hard", "case"], source:"both",
 stem:"Mrs. Patel, 67, takes timolol 0.5% 1 drop OU BID. She tells the pharmacist she often forgets the evening dose. Which category of medication-related problem is this?",
 options:[
  {t:"Indication", correct:false, why:"Indication concerns whether the drug is needed (duplicate, unnecessary, untreated condition); none of these is described."},
  {t:"Effectiveness", correct:false, why:"Effectiveness lists dose too low, frequency or administration; here doses are missed, which her handout places under adherence."},
  {t:"Safety", correct:false, why:"No side effect or unsafe drug is described."},
  {t:"Adherence", correct:true, why:"Forgets to take is listed under adherence in her handout; the patient misses doses of a drug that can work."},
 ],
 teach:"Adherence covers whether the patient takes the medication: not understanding instructions, preferring not to take it, forgetting, a product that is not available, being unable to administer it, and cost. A patient who forgets the evening dose of a twice-daily drop fits forgetting, and she noted that more drug use brings more non-adherence; her handout offers once-daily Timoptic-XE gel.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 16; T@48119, T@48810 11/19"},

{id:"LMA-024", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-cost-gap",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Haddad, 71, is in the Medicare coverage gap and says his glaucoma drops now cost hundreds of dollars. He is thinking of skipping doses. Which category of medication-related problem is this?",
 options:[
  {t:"Adherence", correct:true, why:"Her handout lists cost, including cannot afford the medication, under adherence."},
  {t:"Safety", correct:false, why:"No adverse effect or unsafe drug is described; the risk is skipped doses."},
  {t:"Indication", correct:false, why:"No duplicate or unneeded drug is described; the issue is paying for it."},
  {t:"Effectiveness", correct:false, why:"The drug can work; the risk is that he will not use it."},
 ],
 teach:"Adherence in her handout includes cost: a more cost-effective medication available, and a patient who cannot afford the medication. A patient who says the drops cost too much and plans to skip doses is the cue; she said cost is often an issue in practice. Cost is not a safety or effectiveness problem.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 16; T@48952, T@48119 11/19"},

{id:"LMA-025", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-arthritis",
 tags:["hard", "case"], source:"both",
 stem:"Mrs. Okonkwo, 79, has severe hand arthritis and cannot squeeze the bottle hard enough to get a drop out, so she has skipped her drops for two weeks. Which category of medication-related problem fits best?",
 options:[
  {t:"Safety", correct:false, why:"No adverse reaction or unsafe drug is described; the drop is not reaching the eye."},
  {t:"Adherence", correct:true, why:"Cannot administer the medication is an adherence item in her handout; she used arthritis pressing the bottle as the example of a logistical barrier."},
  {t:"Indication", correct:false, why:"Her need for glaucoma treatment is not in question, and no duplicate or unneeded drug is described."},
  {t:"Effectiveness", correct:false, why:"The drug is not failing; she cannot give the drop, which her handout places under adherence as cannot administer."},
 ],
 teach:"Adherence includes a patient who cannot swallow or administer the medication. Severe hand arthritis that prevents squeezing the bottle is the logistical barrier she described, and it explains a pressure that does not fall even though the drug is appropriate. The pharmacist asks about compliance and technique before changing the drug.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 16; T@48810, T@55782, T@55958 11/19"},

{id:"LMA-026", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-asthma-timolol",
 tags:["hard", "case", "two-facts"], source:"both",
 stem:"Mr. Weiss, 64, has primary open-angle glaucoma and uncontrolled asthma. His eye doctor prescribes timolol. Which category of medication-related problem does the pharmacist identify?",
 options:[
  {t:"Adherence", correct:false, why:"No missed doses or barriers are described."},
  {t:"Indication", correct:false, why:"Glaucoma is a medical indication for IOP-lowering therapy; the issue is the choice of drug for this patient."},
  {t:"Safety", correct:true, why:"Unsafe medication for the patient is a safety item; her handout lists asthma and COPD as a precaution for beta blockers, and timolol is one."},
  {t:"Effectiveness", correct:false, why:"Nothing says timolol fails to lower IOP; the concern is harm."},
 ],
 teach:"A safety problem is an adverse effect or a medication that is unsafe for the patient. Beta blockers carry a precaution in asthma and COPD, and bronchospasm is a listed systemic effect, so timolol for a patient with asthma is an unsafe medication even though it lowers IOP. The cue is a drug that conflicts with the patient's condition.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 16; T@48119 11/19"},

{id:"LMA-027", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-duplicate",
 tags:["hard", "case"], source:"both",
 stem:"A new prescription reads latanoprost 1 gtt OU QHS. The patient's refill history also shows bimatoprost 0.01% 1 gtt OU QHS filled this month. Which category of medication-related problem is this?",
 options:[
  {t:"Adherence", correct:false, why:"The problem lies in the drug list, not in missed or hard-to-give doses."},
  {t:"Effectiveness", correct:false, why:"The frequency written is once daily; the problem is two drugs of one class."},
  {t:"Safety", correct:false, why:"No adverse effect is described."},
  {t:"Indication", correct:true, why:"Duplicate therapy is listed under indication as unnecessary drug therapy; latanoprost and bimatoprost are both prostaglandin analogs."},
 ],
 teach:"Indication asks whether each drug is needed. Duplicate therapy, two drugs of the same class, is unnecessary drug therapy, and so is a drug with no current medical indication. A new prescription for a drug in the class of one just filled is the cue; latanoprost and bimatoprost are both prostaglandin analogs.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 15; T@48119 11/19"},

{id:"LMA-028", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-need-additional",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Joshi, 70, takes a prostaglandin analog, timolol and brimonidine as directed and uses correct technique. Her IOP remains above goal. Which category of medication-related problem is this?",
 options:[
  {t:"Indication: need additional therapy", correct:true, why:"Need additional therapy is listed under indication; the IOP is above goal while she adheres with correct technique."},
  {t:"Adherence: forgets to take", correct:false, why:"She takes the drugs as directed, so forgetting is not the cause."},
  {t:"Safety: allergic reaction", correct:false, why:"No reaction is described."},
  {t:"Effectiveness: incorrect administration", correct:false, why:"Incorrect administration is an effectiveness item for a wrong technique; her technique is correct."},
 ],
 teach:"When IOP stays above goal although the patient adheres and uses correct technique, the regimen is not enough, which her handout lists under indication as need additional therapy. The pharmacist rules out compliance and administration technique first, then adds another agent. A faulty technique or missed doses would point to a different category.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 15; T@48119, T@55782 11/19"},

{id:"LMA-029", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-more-effective",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Tran, 58, takes latanoprost once daily every evening with good technique, and his eye doctor says it is not lowering IOP as expected. Which category of medication-related problem is this?",
 options:[
  {t:"Adherence: forgets the evening dose of the drop", correct:false, why:"He takes it every evening, so missed doses are not the issue."},
  {t:"Effectiveness: more effective drug available", correct:true, why:"More effective medication available is an effectiveness item; she said latanoprost has lower efficacy than bimatoprost in the same class."},
  {t:"Safety: dose too high for the patient", correct:false, why:"Once daily is the usual frequency, so no excess dose is described."},
  {t:"Indication: duplicate therapy of the same class", correct:false, why:"He takes one agent, so no duplicate therapy exists."},
 ],
 teach:"Effectiveness covers a suboptimal drug or a more effective medication being available. An adherent patient with correct technique whose IOP is not falling as expected fits it, and within the prostaglandin analogs she said latanoprost has lower efficacy than bimatoprost, so bimatoprost is the switch. Missed doses would point to adherence instead.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 15, 23; T@71578, T@56607 11/19"},

{id:"LMA-030", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-bak-stinging",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Cohen, 66, develops burning, redness and tearing after each drop of a multi-dose glaucoma bottle that contains benzalkonium chloride. Which category of medication-related problem is this?",
 options:[
  {t:"Indication: unnecessary drug therapy", correct:false, why:"Unnecessary drug therapy means a drug without a need; he still needs treatment, and the problem is a reaction."},
  {t:"Adherence: does not understand instructions", correct:false, why:"He understands the instructions; the problem begins after each drop."},
  {t:"Safety: undesirable effect", correct:true, why:"Her handout lists undesirable effect and adverse drug reaction under safety, and a reaction to the preservative BAK, common in multi-dose bottles, is one."},
  {t:"Effectiveness: dose too low", correct:false, why:"Dose too low would mean too little effect; burning and redness are adverse effects."},
 ],
 teach:"A safety problem includes an undesirable effect or adverse reaction. Multi-dose eye drops contain a preservative, most commonly benzalkonium chloride (BAK), which can be quite irritating, so burning, redness and tearing after each drop from such a bottle point to a reaction to it. Her solution is a preservative-free product in individual containers.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 16, 22; T@54358, T@54408 11/19"},

{id:"LMA-031", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-which-indication",
 tags:["hard", "tell"], source:"both",
 stem:"Which of the following is an indication problem?",
 options:[
  {t:"A patient cannot afford the drops", correct:false, why:"Cost, including cannot afford, is listed under adherence."},
  {t:"A patient forgets the evening dose", correct:false, why:"Forgets to take is listed under adherence."},
  {t:"Timolol prescribed to a patient with uncontrolled asthma", correct:false, why:"Unsafe medication for the patient is a safety item; timolol carries an asthma precaution."},
  {t:"Two prostaglandin analogs prescribed together", correct:true, why:"Duplicate therapy is listed under indication as unnecessary drug therapy; two prostaglandin analogs are one class twice."},
 ],
 teach:"Indication asks whether each drug is needed: unnecessary therapy (duplicate, no medical indication, nonmedication therapy appropriate), an untreated condition, or a need for additional therapy. Cost and forgetting belong to adherence, and an unsafe drug to safety. Sorting a case starts with asking whether the problem is need, effect, harm, or the patient's ability to use the drug.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 15–16; T@48119, T@48952 11/19"},

{id:"LMA-032", skill:"case", prof:'Lam', tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-adherence-select", multi:true,
 tags:["hard", "multi"], source:"both",
 stem:"Which of the following are adherence problems? Select all that apply.",
 options:[
  {t:"Cannot afford the medication", correct:true, why:"Cost, including cannot afford the medication, is listed under adherence."},
  {t:"Two drugs of the same class prescribed", correct:false, why:"Duplicate therapy is listed under indication, not adherence."},
  {t:"Forgets to take the evening dose", correct:true, why:"Forgets to take is listed under adherence."},
  {t:"Does not understand the instructions", correct:true, why:"Does not understand instructions is the first item under adherence."},
  {t:"Frequency more often than recommended", correct:false, why:"Frequency inappropriate is listed under effectiveness and under safety, not adherence."},
 ],
 teach:"Adherence collects the reasons a patient is not taking the drug as prescribed: not understanding instructions, preferring not to take it, forgetting, a product not available, being unable to administer it, and cost. Duplicate therapy belongs to indication, and a wrong frequency belongs to effectiveness or safety. The cue is a patient-side barrier, not a prescribing error.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 16; T@48119, T@48952 11/19"},

{id:"LMA-033", skill:"case", prof:'Lam', lowYield:true, tier:'new', topic:"lm-assess", sub:"mrp", concept:"lm-assess-sig-eye",
 tags:["hard", "case", "sig"], source:"both",
 stem:"A 70-year-old man has glaucoma in the left eye only. His prescription for latanoprost reads 1 gtt OS QHS. How should the pharmacist read the instructions?",
 options:[
  {t:"One drop in the left eye in the evening", correct:true, why:"GTT is drop, OS is the left eye and QHS is in the evening, so the sig is one drop in the left eye in the evening."},
  {t:"One drop in the right eye in the morning", correct:false, why:"OD is the right eye and QAM is the morning; both abbreviations differ from the sig."},
  {t:"One drop in both eyes in the evening", correct:false, why:"OU is both eyes; this sig says OS, the left eye alone."},
  {t:"One drop in the left eye in the morning", correct:false, why:"The left eye is right, but QAM is the morning and QHS is the evening."},
 ],
 teach:"A sig is read term by term: GTT is drop, OD right eye, OS left eye, OU both eyes, QAM in the morning, QPM or QHS in the evening, and QD, BID, TID and QID are one to four times a day. For disease in the left eye, OS is the cue; OU would mean both eyes.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 4; T@40383 11/19"},

{id:"LMA-035", skill:"class", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-first-line",
 tags:["hard"], source:"both",
 stem:"Which class of ophthalmic agent is first line for primary open-angle glaucoma?",
 options:[
  {t:"Beta blockers", correct:false, why:"Her handout lists beta blockers as adjunctive or alternative; they reduce IOP 20-30%, less than prostaglandin analogs, and the solutions are twice daily."},
  {t:"Prostaglandin analogs", correct:true, why:"First line because of once-daily dosing, which supports adherence, an IOP reduction up to 33%, lower-cost generics and good tolerance."},
  {t:"Alpha-2 adrenergic agonists", correct:false, why:"Adjunctive or alternative; the 18-27% IOP reduction is below that of prostaglandin analogs."},
  {t:"Topical carbonic anhydrase inhibitors", correct:false, why:"Topical carbonic anhydrase inhibitors reduce IOP 15-26% and are dosed three times daily, so they come later in the sequence."},
 ],
 teach:"She orders the classes from most to least commonly prescribed, and the first combines the largest IOP reduction with the simplest schedule: prostaglandin analogs, once daily with up to 33% reduction, against 15-30% for the later classes. Beta blockers and alpha-2 agonists are adjunctive or alternative agents. The 'prost' in the name identifies the class.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 19; T@50934 11/19"},

{id:"LMA-036", skill:"class", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-profile",
 tags:["hard", "two-facts"], source:"both",
 stem:"A patient needs the initial IOP target of 25-30% lower, with adherence in mind. Which profile describes why a prostaglandin analog is chosen first?",
 options:[
  {t:"20-30% IOP reduction with twice-daily dosing", correct:false, why:"That is the beta blocker profile in her handout; its range reaches below the 25-30% target and needs two doses a day."},
  {t:"18-27% IOP reduction with twice-daily dosing", correct:false, why:"That is the alpha-2 agonist profile; its range sits largely below the 25-30% target."},
  {t:"15-26% IOP reduction with three-times-daily dosing", correct:false, why:"That is the topical carbonic anhydrase inhibitor profile: the lowest reduction and the most doses."},
  {t:"Up to 33% IOP reduction with once-daily dosing", correct:true, why:"Up to 33% reaches the 25-30% target, and one dose a day supports adherence."},
 ],
 teach:"She compares each class's percent IOP reduction with the 25-30% target and with how often the drug must be given, since more drug use brings more non-adherence. Prostaglandin analogs reduce IOP up to 33% with one dose a day; each later class reduces less (15-30%) and needs two or three doses.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 20; T@51508, T@51016 11/19"},

{id:"LMA-037", skill:"class", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-reasons-select", multi:true,
 tags:["hard", "multi"], source:"both",
 stem:"Which are reasons prostaglandin analogs are first-line therapy? Select all that apply.",
 options:[
  {t:"Preservative-free multi-dose bottles are the standard", correct:false, why:"Multi-dose bottles contain a preservative; preservative-free products are individual single-use containers, which she offered as a remedy for a reaction to the preservative."},
  {t:"Lower-cost generics are available", correct:true, why:"Several generics have been on the market a long time, so the cost is low."},
  {t:"Once-daily dosing", correct:true, why:"One dose a day supports better adherence from the patient's standpoint."},
  {t:"Up to 33% reduction in IOP", correct:true, why:"A reduction of up to 33% meets the 25-30% target."},
  {t:"Good tolerance", correct:true, why:"Good tolerance means efficacy is balanced with a favorable safety profile."},
  {t:"Efficacy improves with a second daily dose", correct:false, why:"More than once daily decreases efficacy; it does not improve it."},
 ],
 teach:"She gave the reasons prostaglandin analogs come first: once-daily dosing that supports adherence, a significant IOP reduction of up to 33%, low cost through generics, and good tolerance. Efficacy is balanced against safety, and extra doses add no effect. Each reason in an item ties to adherence, efficacy, cost or tolerance.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 20; T@50934, T@51016, T@51508, T@51718 11/19"},

{id:"LMA-039", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-latanoprost-tid",
 tags:["hard", "case", "reverse"], source:"both",
 stem:"Ms. Greene, 73, has been told by a relative that more drops lower pressure faster, so she uses her latanoprost three times a day. Her IOP is not improving. What explains this?",
 options:[
  {t:"The dose is too low, so she should add a fourth drop", correct:false, why:"Efficacy falls when the frequency rises above once daily, so a fourth drop would worsen the response."},
  {t:"Nasal drainage is carrying the drug away from the eye", correct:false, why:"Eyelid closure reduces nasolacrimal drainage and systemic absorption; it does not explain failure at three times daily."},
  {t:"More often than once daily decreases efficacy", correct:true, why:"She said that going above once daily decreases efficacy, so three daily drops explain the poor response."},
  {t:"Latanoprost works at night, not in the daytime", correct:false, why:"The drug can be used in the daytime; nightly dosing is advised because of blurred vision, not because the drug works at night."},
 ],
 teach:"For a prostaglandin analog, more doses do not mean more effect: going above once daily decreases efficacy. A patient whose IOP is not improving while she uses the drop several times a day is the cue, and the pharmacist corrects the frequency to once daily. The single daily dose is also the source of the drug's adherence advantage.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 20; T@51238 11/19"},

{id:"LMA-043", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-latisse",
 tags:["hard", "case"], source:"both",
 stem:"A 66-year-old woman with newly diagnosed primary open-angle glaucoma brings a prescription for Latisse (bimatoprost). What is the problem?",
 options:[
  {t:"Latisse is a beta blocker and is dosed twice daily", correct:false, why:"Latisse is bimatoprost, a prostaglandin analog, not a beta blocker, and it is not dosed twice daily."},
  {t:"Latisse is for eyelash growth; Lumigan is for glaucoma", correct:true, why:"Bimatoprost has two indications by brand and concentration: Lumigan for glaucoma and Latisse for eyelash hypotrichosis."},
  {t:"Latisse is correct for glaucoma and no change is needed", correct:false, why:"Latisse is indicated for eyelash growth, so it would not treat her glaucoma."},
  {t:"Latisse is an oral carbonic anhydrase inhibitor", correct:false, why:"Latisse is an ophthalmic prostaglandin analog, not an oral drug; the oral carbonic anhydrase inhibitors are acetazolamide and methazolamide."},
 ],
 teach:"One drug can carry two indications under different brand names and concentrations. Bimatoprost is Lumigan for glaucoma and Latisse for eyelash hypotrichosis, inadequate eyelash growth. A glaucoma patient handed a Latisse prescription has been given the eyelash product, although both contain a prostaglandin analog.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 19; T@50727, T@50766 11/19"},

{id:"LMA-046", skill:"class", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-which-prost",
 tags:["hard", "class"], source:"both",
 stem:"Which drug is a prostaglandin analog?",
 options:[
  {t:"Timolol", correct:false, why:"Timolol ends in -olol, the stem of a beta blocker."},
  {t:"Tafluprost", correct:true, why:"Tafluprost (Zioptan) contains 'prost', which she used to recognize prostaglandin analogs."},
  {t:"Brinzolamide", correct:false, why:"Brinzolamide ends in -zolamide, the stem of a carbonic anhydrase inhibitor."},
  {t:"Brimonidine", correct:false, why:"Brimonidine (Alphagan P) is an alpha-2 adrenergic agonist."},
 ],
 teach:"Her way to recognize a prostaglandin analog is the 'prost' in the generic name, as in bimatoprost, latanoprost, travoprost and tafluprost. Other classes have their own stems: -olol for beta blockers and -zolamide for carbonic anhydrase inhibitors. Reading the stem identifies the class before the dose or frequency is checked.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 19; T@50548 11/19"},

{id:"LMA-047", skill:"class", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-prodrug",
 tags:["hard", "class"], source:"both",
 stem:"What is latanoprostene bunod (Vyzulta)?",
 options:[
  {t:"A prodrug of bimatoprost", correct:false, why:"Vyzulta is the prodrug of latanoprost, not of bimatoprost (Lumigan, Latisse)."},
  {t:"A combination of latanoprost and timolol", correct:false, why:"Timolol combination products are Cosopt (with dorzolamide) and Combigan (with brimonidine); Vyzulta is one drug."},
  {t:"A prodrug of latanoprost", correct:true, why:"Latanoprostene bunod is a prodrug of latanoprost, so it is a prostaglandin analog."},
  {t:"A combination of latanoprost and netarsudil", correct:false, why:"Latanoprost plus netarsudil is Rocklatan, a separate product."},
 ],
 teach:"Her handout identifies Vyzulta (latanoprostene bunod) as a prodrug of latanoprost, which places it in the prostaglandin analog class. Rocklatan is a different kind of product: latanoprost combined with netarsudil. A single-ingredient name that contains latanoprost points to latanoprost, not to bimatoprost or a combination.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 19; T@50548 11/19"},

{id:"LMA-048", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-asthma-first",
 tags:["hard", "case", "two-facts"], source:"both",
 stem:"Mrs. Silva, 70, has newly diagnosed primary open-angle glaucoma and uncontrolled asthma. No contraindications to other drugs are noted. Which agent is the most appropriate first choice?",
 options:[
  {t:"Timolol 0.5%", correct:false, why:"Beta blockers carry a precaution in asthma and COPD, and bronchospasm is a listed systemic effect."},
  {t:"Pilocarpine 2%", correct:false, why:"Pilocarpine is dosed four times daily and has an asthma precaution in her handout, so it is neither first line nor suited to her."},
  {t:"Dorzolamide 2%", correct:false, why:"A topical carbonic anhydrase inhibitor is dosed three times daily with a 15-26% reduction and sits later in the sequence than first line."},
  {t:"Latanoprost", correct:true, why:"Prostaglandin analogs are first line, and her handout lists no asthma precaution for them, unlike beta blockers and pilocarpine."},
 ],
 teach:"First line is the prostaglandin analog class. Her precautions attach asthma to beta blockers (asthma and COPD) and to pilocarpine (asthma), not to prostaglandin analogs, whose contraindications are macular edema and a history of herpetic keratitis. A glaucoma patient with asthma therefore starts on a prostaglandin analog; timolol, the nearest wrong option, adds a bronchospasm risk.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 20; T@50934, T@51016 11/19"},

{id:"LMA-050", skill:"counsel", prof:'Lam', tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-night",
 tags:["hard", "counsel"], source:"both",
 stem:"Which side effect of prostaglandin analogs is the reason patients are told to instill the drop at night?",
 options:[
  {t:"Stinging", correct:false, why:"Stinging is a side effect of the class, but she did not give it as the reason for night dosing."},
  {t:"Blurred vision", correct:true, why:"She said blurry vision is why the drug is dosed at night, although it can be used in the daytime."},
  {t:"Increased iris pigmentation", correct:false, why:"Iris pigmentation is a side effect of the class, but she did not give it as the reason for night dosing."},
  {t:"Eyelash growth", correct:false, why:"Eyelash growth is a side effect of the class, but she did not give it as the reason for night dosing."},
 ],
 teach:"Prostaglandin analogs can blur vision after the drop, and she said that is why patients are told to use them at night, though daytime use is possible. A patient who asks when to instill the drop, or reports blurred vision after a morning dose, is the cue. Stinging, pigmentation and lash growth are not the reason for the timing.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 21; T@52973 11/19"},

{id:"LMA-051", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-foreign-body",
 tags:["hard", "case", "counsel"], source:"both",
 stem:"Three days after starting latanoprost, Mr. Adeyemi, 65, reports a feeling that something is in his eye after each drop. What should the pharmacist tell him?",
 options:[
  {t:"A contraindication to the drug, so he should stop it today", correct:false, why:"Foreign body sensation is a listed side effect, not a contraindication; her contraindications are macular edema and a history of herpetic keratitis."},
  {t:"Bottle contamination, so he should discard the bottle now", correct:false, why:"Foreign body sensation is a known effect of the class; avoiding contamination is a technique point, not the cause here."},
  {t:"An expected side effect; call the eye doctor if intolerable", correct:true, why:"She listed foreign body sensation among the common side effects; when a patient cannot tolerate it, the plan is to talk with the eye doctor."},
  {t:"A sign the drug has started to work, so continue as is", correct:false, why:"The sensation is an adverse effect and does not show efficacy; efficacy is judged by IOP reduction at follow-up."},
 ],
 teach:"Foreign body sensation, blurry vision, stinging, iris pigmentation and eyelash growth are the effects she expects pharmacists to counsel on. A patient reporting the feeling of something in the eye soon after starting latanoprost is describing one of these. If he cannot tolerate it, he talks with the ophthalmologist about changing the formulation, the class or the preservative.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 21–22; T@53638, T@52282 11/19"},

{id:"LMA-052", skill:"adverse", prof:'Lam', tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-reverse-lashes",
 tags:["hard", "reverse"], source:"both",
 stem:"A woman with glaucoma notices darker iris color and longer, thicker eyelashes after a new once-daily drop. Which drug class is most likely responsible?",
 options:[
  {t:"Beta blocker", correct:false, why:"Stinging, dry eyes, blepharitis and blurred vision are beta blocker local effects; none is pigmentation or lash growth."},
  {t:"Alpha-2 agonist", correct:false, why:"Lid edema, eye discomfort, foreign-object sensation and itching are alpha-2 agonist local effects."},
  {t:"Topical carbonic anhydrase inhibitor", correct:false, why:"Stinging or burning, ocular discomfort, blurred vision and tearing are the topical carbonic anhydrase inhibitor effects."},
  {t:"Prostaglandin analog", correct:true, why:"Iris pigmentation and eyelash growth are effects of prostaglandin analogs; Latisse is bimatoprost marketed for eyelashes."},
 ],
 teach:"Darker iris color and longer eyelashes identify a prostaglandin analog among the glaucoma classes. Her list for the class includes blurry vision, iris pigmentation, foreign body sensation, stinging and eyelash growth, and Latisse is the eyelash product containing bimatoprost. Other classes have different local effects, so pigmentation with lash growth is the cue.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 21; T@52443, T@50766 11/19"},

{id:"LMA-053", skill:"adverse", prof:'Lam', tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-effects-select", multi:true,
 tags:["hard", "multi"], source:"both",
 stem:"Which effects are associated with prostaglandin analogs? Select all that apply.",
 options:[
  {t:"Increased iris pigmentation", correct:true, why:"Iris pigmentation was one of the effects she named for the class."},
  {t:"Blurred vision", correct:true, why:"Blurry vision is the effect that is the reason for dosing at night."},
  {t:"Drowsiness with fatigue", correct:false, why:"Drowsiness is the most common systemic effect of the alpha-2 agonists, not of prostaglandin analogs."},
  {t:"Bradycardia and low blood pressure", correct:false, why:"Bradycardia and hypotension are systemic effects of beta blockers."},
  {t:"Stinging", correct:true, why:"A little bit of stinging was among the effects she listed for the class."},
  {t:"Eyelash growth", correct:true, why:"Eyelash growth is an effect she named, and it is why bimatoprost is also sold as Latisse."},
 ],
 teach:"The effects of prostaglandin analogs she listed are blurry vision, iris pigmentation, foreign body sensation, stinging and eyelash growth, all local to the eye. Systemic effects such as drowsiness and bradycardia belong to other classes, alpha-2 agonists and beta blockers. Counseling covers these effects so the patient is not surprised.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 21; T@52282, T@52443 11/19"},

{id:"LMA-054", skill:"adverse", prof:'Lam', lowYield:true, tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-contraindication",
 tags:["hard", "tell"], source:"both",
 stem:"Which history is a contraindication to a prostaglandin analog?",
 options:[
  {t:"Herpetic keratitis", correct:true, why:"Herpetic keratitis and macular edema are the two contraindications she pointed out for the class."},
  {t:"Asthma", correct:false, why:"Asthma is a precaution for beta blockers and pilocarpine."},
  {t:"Stroke", correct:false, why:"A history of stroke is a precaution for alpha-2 agonists."},
  {t:"Sickle cell disease", correct:false, why:"Sickle cell disease is a precaution for carbonic anhydrase inhibitors."},
 ],
 teach:"Prostaglandin analogs have few contraindications; her handout lists macular edema and a history of herpetic keratitis. Each other class has its own precaution: asthma for beta blockers and pilocarpine, stroke and cardiovascular or kidney disease for alpha-2 agonists, and sickle cell disease for carbonic anhydrase inhibitors.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 21; T@53313 11/19"},

{id:"LMA-055", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-bak",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Park, 64, has red, burning eyes after every drop of a multi-dose prostaglandin analog bottle that contains benzalkonium chloride. His prescriber's choices include tafluprost, which is preservative free. What is the best step?",
 options:[
  {t:"Ask about a preservative-free single-use product", correct:true, why:"Her remedy for a reaction to the preservative (BAK) is a preservative-free product in individual single-use containers; tafluprost is an example."},
  {t:"Increase the frequency to twice daily for better effect", correct:false, why:"Twice daily decreases efficacy and leaves the preservative in the eye."},
  {t:"Switch to an oral carbonic anhydrase inhibitor", correct:false, why:"Oral carbonic anhydrase inhibitors are for short term use because of systemic side effects; the reaction is to a preservative, solved within the class."},
  {t:"Add pilocarpine four times daily to the drop", correct:false, why:"Adding pilocarpine adds a drop to the regimen and does not remove the preserved bottle."},
 ],
 teach:"All multi-dose eye drops contain a preservative, most commonly benzalkonium chloride (BAK), which can irritate the eye. When a patient reacts to it, she recommends a non-preservative product, the individual single-use form; among prostaglandin analogs, Xelpros latanoprost and tafluprost are preservative free. Raising the frequency does not remove the preservative.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 22; T@54408, T@54727, T@55501 11/19"},

{id:"LMA-057", skill:"tell", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-pf-recognize",
 tags:["hard", "tell"], source:"both",
 stem:"A pharmacist is asked how to tell that an ophthalmic product is preservative free. Which feature is the best clue?",
 options:[
  {t:"A gel-forming solution", correct:false, why:"A gel-forming solution is a formulation change used to manage intolerance; it does not mark a product as preservative free."},
  {t:"A suspension that is shaken", correct:false, why:"A suspension is a formulation type that is shaken before use; it carries no preservative-free marker."},
  {t:"Individual single-use containers", correct:true, why:"Individual single-use containers are the preservative-free products she described."},
  {t:"Storage in the refrigerator before opening", correct:false, why:"Refrigeration before opening is a storage instruction (latanoprost, tafluprost, Vyzulta) unrelated to the preservative."},
 ],
 teach:"Preservative-free eye drops come as individual single-use containers, while multi-dose bottles contain a preservative. A patient asking how to spot a preservative-free product, or one who reacts to benzalkonium chloride, is the cue. These products can cost a little more. Gel, suspension and storage features describe other properties of a product.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 22; T@55319, T@54727 11/19"},

{id:"LMA-058", skill:"counsel", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-pf-tradeoff",
 tags:["hard", "case", "counsel"], source:"both",
 stem:"Ms. Ibarra, 60, asks why her preservative-free single-use prostaglandin analog costs more than the multi-dose bottle. What is the best explanation?",
 options:[
  {t:"It is a different drug class with a stronger effect", correct:false, why:"Preservative-free describes the container, not a new drug class or a stronger effect."},
  {t:"It is dosed more often, so more is dispensed", correct:false, why:"The frequency stays once daily; a preservative-free product does not change the dosing."},
  {t:"The multi-dose bottle is not a prostaglandin analog", correct:false, why:"Multi-dose bottles of the same drug exist with a preservative; they are not a different class."},
  {t:"Each container is single use, so it costs more", correct:true, why:"Individual single-use containers can be a little more expensive, and they help patients who react to the preservative."},
 ],
 teach:"A preservative-free product is a different package, the individual single-use container, not a different drug or class, and she said it can cost a little more. The trade-off is cost against irritation from the preservative, so a patient who asks about the price is told what the extra expense provides. If cost then blocks use, it becomes an adherence problem.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 22; T@54854, T@55319 11/19"},

{id:"LMA-059", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-intolerance-plan",
 tags:["hard", "case"], source:"both",
 stem:"Mrs. Lee, 72, cannot tolerate blurred vision and foreign body sensation from her prostaglandin analog solution. What should the pharmacist suggest she discuss with her ophthalmologist?",
 options:[
  {t:"Change the formulation or switch the class", correct:true, why:"Changing the formulation (solution to gel) and switching to another class are both on her list for managing intolerance."},
  {t:"Use the drop four times daily so she adapts", correct:false, why:"Four times daily decreases the efficacy of this once-daily class and does not remove the side effects."},
  {t:"Stop treatment for a few months to recover", correct:false, why:"Therapy is needed to reduce IOP; the options for intolerance change the product or class and do not stop treatment."},
  {t:"Double the number of drops at bedtime each night", correct:false, why:"More than once daily decreases efficacy, and extra drops do not address the intolerance."},
 ],
 teach:"For side effects a patient cannot tolerate, the pharmacist suggests talking to the ophthalmologist about three options: changing the formulation (a solution to a gel can be better tolerated), switching to a different class such as a topical beta blocker, or addressing the preservative. Blurry vision and foreign body sensation are the effects she named.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 22; T@53638, T@53848, T@53962 11/19"},

{id:"LMA-060", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-first-step-inadequate",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Taylor, 67, has used latanoprost for six weeks and his IOP is still above goal. What should the pharmacist do first?",
 options:[
  {t:"Add pilocarpine to the current regimen today", correct:false, why:"Adding an agent is a step after compliance and administration technique are checked."},
  {t:"Ask about adherence and drop technique", correct:true, why:"Her first step for an inadequate response is to inquire about compliance and eye administration technique."},
  {t:"Increase latanoprost to twice daily dosing", correct:false, why:"More than once daily decreases efficacy, so twice daily would not help."},
  {t:"Switch to bimatoprost, which is slightly more effective", correct:false, why:"Switching within the class is for a patient who is adherent with correct technique and still has an inadequate response."},
 ],
 teach:"When IOP does not reach the goal, the pharmacist first asks whether the drug is reaching the eye: compliance and administration technique, since limits such as arthritis can block the drop. After both are confirmed, the plan is to switch to another agent in the same class or add another agent.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 23; T@55782, T@55958 11/19"},

{id:"LMA-061", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-switch-bimatoprost",
 tags:["hard", "case"], source:"both",
 stem:"Ms. Yusuf, 69, is adherent, uses correct technique and has an inadequate response to latanoprost. Her prescriber wants to switch within the class. Which agent is slightly more effective at lowering IOP than the one she uses?",
 options:[
  {t:"Latanoprost (Xalatan)", correct:false, why:"Latanoprost is the drug she already uses with an inadequate response; she said it has lower efficacy than bimatoprost."},
  {t:"Betaxolol (Betoptic)", correct:false, why:"Betaxolol is a beta blocker; the switch asked for is within the prostaglandin analog class."},
  {t:"Bimatoprost (Lumigan)", correct:true, why:"Her handout says bimatoprost is slightly more effective and is the switch for patients unresponsive to latanoprost."},
  {t:"Brimonidine (Alphagan P)", correct:false, why:"Brimonidine (Alphagan P) is an alpha-2 agonist, a different class."},
 ],
 teach:"The prostaglandin analogs differ slightly in how they interact with the receptor, so one can work better than another. She said latanoprost has lower efficacy than bimatoprost, so bimatoprost is the in-class switch when latanoprost does not lower IOP enough. A drug from another class would be an addition or an alternative, not a switch within the class.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 23; T@71578, T@56607 11/19"},

{id:"LMA-062", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"prob", concept:"lm-pga-bimatoprost-fail",
 tags:["hard", "case", "two-facts"], source:"both",
 stem:"Mr. Costa, 63, is adherent with correct technique, but his IOP is above goal on bimatoprost 0.01% 1 gtt OU QHS. What is the most appropriate next step?",
 options:[
  {t:"Switch to latanoprost, which is slightly more effective", correct:false, why:"Latanoprost has lower efficacy than bimatoprost, so switching to it is a step down."},
  {t:"Increase bimatoprost to twice daily", correct:false, why:"More than once daily decreases efficacy."},
  {t:"Switch to over-the-counter brimonidine", correct:false, why:"OTC brimonidine (Lumify) is formulated for eye redness and not for glaucoma."},
  {t:"Add timolol, the next class in the sequence", correct:true, why:"He already uses the more effective prostaglandin analog, so with adherence and technique confirmed the plan is to add another agent, and timolol is the next class."},
 ],
 teach:"Bimatoprost is the more effective of the two prostaglandin analogs, of the two she compared, latanoprost and bimatoprost. After adherence and technique are confirmed, the plan is to add an agent from the next class in her sequence, the beta blocker. The nearest wrong option, latanoprost, is the lower-efficacy agent, which would be a step down.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 23; T@71578, T@56607 11/19"},

{id:"LMA-063", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"case", concept:"lm-pga-cost-generic",
 tags:["hard", "case"], source:"both",
 stem:"Mr. Alvarez, 74, is on a fixed income and cannot afford the brand prostaglandin analog his eye doctor prescribed. What is the most appropriate pharmacist response?",
 options:[
  {t:"Ask about a lower-cost generic prostaglandin", correct:true, why:"Prostaglandin analogs have lower-cost generics, and cost is an adherence problem solved by a cheaper effective drug in the same class."},
  {t:"Switch him to over-the-counter brimonidine drops", correct:false, why:"OTC brimonidine is formulated for eye redness and not for glaucoma."},
  {t:"Suggest using the brand drop on alternate days", correct:false, why:"Once daily is the frequency of this drug; skipping days changes the prescription and does not lower its cost."},
  {t:"Replace it with oral acetazolamide for glaucoma", correct:false, why:"Oral acetazolamide is for short term use because of systemic side effects and does not replace a first-line drop."},
 ],
 teach:"Cost is an adherence problem, and her handout lists a more cost-effective medication under it. Prostaglandin analogs are first line partly because several generics have been on the market a long time and are inexpensive, so a patient who cannot pay for the brand is moved to a generic of the same class.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 16, 20; T@48952, T@51718 11/19"},

{id:"LMA-065", skill:"counsel", prof:'Lam', tier:'new', topic:"lm-pga", sub:"ae", concept:"lm-pga-select-counsel", multi:true,
 tags:["hard", "multi", "counsel"], source:"both",
 stem:"Which counseling points apply to a patient starting latanoprost? Select all that apply.",
 options:[
  {t:"Expect the heart rate to slow and the blood pressure to fall", correct:false, why:"Bradycardia and hypotension are systemic effects of beta blockers, not of latanoprost."},
  {t:"Report a color change of the iris or eyelashes", correct:true, why:"Pigmentation and eyelash growth are effects of this class, so the patient should know to report them."},
  {t:"Use it three times a day for better control", correct:false, why:"Three times daily goes above once daily, which decreases efficacy."},
  {t:"Instill it in the evening because it can blur vision", correct:true, why:"Blurred vision is the reason prostaglandin analogs are given at night."},
  {t:"Use one drop in each affected eye once daily", correct:true, why:"Once daily, one drop in each affected eye, is the frequency for the class."},
 ],
 teach:"Counseling for a prostaglandin analog covers the once-daily frequency (more often decreases efficacy), evening use because the drug can blur vision, and the local effects: stinging, foreign body sensation, iris pigmentation and eyelash growth. Heart rate and blood pressure effects belong to beta blockers. Patients complain when effects were not mentioned, which is why she stressed counseling.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slides 20–21; T@51016, T@53064, T@52443 11/19"},

{id:"LMA-066", skill:"case", prof:'Lam', tier:'new', topic:"lm-pga", sub:"why", concept:"lm-pga-rocklatan",
 tags:["hard", "class"], source:"both",
 stem:"A patient is prescribed latanoprost plus netarsudil as one product (Rocklatan). Which statement describes the product?",
 options:[
  {t:"A prostaglandin analog combined with a beta blocker", correct:false, why:"Rocklatan adds netarsudil, a Rho kinase inhibitor; the beta blocker combinations are Cosopt and Combigan."},
  {t:"A prostaglandin analog combined with an alpha-2 agonist", correct:false, why:"The alpha-2 agonist combinations in her handout are Combigan and Simbrinza; neither contains a prostaglandin analog."},
  {t:"A prostaglandin analog combined with a Rho kinase inhibitor", correct:true, why:"Rocklatan is latanoprost plus netarsudil, and netarsudil (Rhopressa) is the Rho kinase inhibitor."},
  {t:"A beta blocker combined with a topical carbonic anhydrase inhibitor", correct:false, why:"Dorzolamide plus timolol is Cosopt, a carbonic anhydrase inhibitor and beta blocker combination without a prostaglandin analog."},
 ],
 teach:"Netarsudil is a Rho kinase inhibitor sold alone as Rhopressa and combined with latanoprost as Rocklatan, so Rocklatan pairs a prostaglandin analog with a Rho kinase inhibitor. Her other combination products pair a beta blocker with a carbonic anhydrase inhibitor or an alpha-2 agonist, or an alpha-2 agonist with a carbonic anhydrase inhibitor. The second ingredient identifies the second class.",
 cite:"Lecture 12 (Lam_Glaucoma.pdf) slide 19; T@50548 11/19"},
);
